head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > P > fixedColumnLineDiv]<br/>고정된 Column 과 고정되지 않은 Column 의 경계를 Div 요소로 표시할지 설정합니다.",
    "validation" : [
        "미설정 또는 false 설정 시 고정된 Column 과 고정되지 않은 Column 의 경계에 별도 요소를 추가하지 않습니다.",
		"true 설정 시 fixedColumn 또는 fixedRightColumn 속성으로 고정된 Column 과 고정되지 않은 Column 의 경계에 Div 요소를 추가하여 표시합니다.",
        "Div 요소에는 w2grid_fixedcolumn_line_div 또는 w2grid_fixedrightcolumn_line_div 클래스가 설정됩니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {   
    // 기존 target 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }

    if (typeof target1 !== 'undefined') {
        target1.remove();
    }    

    // 조건 설정   
    let properties = {
        fixedColumn: 2,
        fixedColumnLineDiv: con_fixedColumnLineDiv.getText(),
        dataList: "data:dlt_bind",      
    };

    let cList = $c.gcm.createCList(properties);      
    // let eList = $c.gcm.createEList([]) 

    // dataList 생성
    $c.gcm.createBasicDataList('', '', 'dlt_bind');

    // target 생성
    let grp_comp = document.querySelector('.tc_group_basic');  
    let strTarget = '';
    let strNameSpace = $c.gcm.getNameSpace();

    strTarget += '<w2:gridView ' + strNameSpace + ' ' + cList + ' checkAllType="false" id="" style="width:250px;height:300px;">';
    strTarget += '<w2:caption style="" id="caption1" value="this is a grid caption."></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="70" style="" inputType="text" id="column1" value="name1"></w2:column>';
    strTarget += '<w2:column width="70" style="" inputType="text" id="column2" value="name2"></w2:column>';
    strTarget += '<w2:column width="70" style="" inputType="text" id="column3" value="name3"></w2:column>';
    strTarget += '<w2:column width="70" style="" inputType="text" id="column4" value="name4"></w2:column>';
    strTarget += '<w2:column width="70" style="" inputType="text" id="column5" value="name5"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    strTarget += '<w2:column width="70" style="" inputType="text" id="col1" value=""></w2:column>';
    strTarget += '<w2:column width="70" style="" inputType="text" id="col2" value=""></w2:column>';
    strTarget += '<w2:column width="70" style="" inputType="text" id="col3" value=""></w2:column>';
    strTarget += '<w2:column width="70" style="" inputType="text" id="col4" value=""></w2:column>';
    strTarget += '<w2:column width="70" style="" inputType="text" id="col5" value=""></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';    

    // target 생성
    scwin["target1"] = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );

    scwin.btn_fixedColumnLineDiv_onclick();
}



scwin.btn_fixedColumnLineDiv_onclick = function (e) {
    let targetElement = document.querySelector('div[id*="target1_fixedColumnDiv"]');

    if (targetElement) {
        const style = window.getComputedStyle(targetElement);
        const borderRightValue = style.borderRight;
        const classValue = targetElement.className;

        wf_body_bottom.getObj("scwin").setReturnValue("column 경계 표시"); 
        wf_body_bottom.getObj("scwin").setReturnValue(`borderRight : ${borderRightValue}`);
        wf_body_bottom.getObj("scwin").setReturnValue(`class : ${classValue}`)
    }
    else {
        wf_body_bottom.getObj("scwin").setReturnValue("column 경계 미표시");    
    }        
};
